// Process the files list and add company info
const folderName = $node["Google Drive Trigger"].json.name;
const folderId = $node["Google Drive Trigger"].json.id;
const response = $input.first().json;

const files = response.files || [];

if (files.length === 0) {
  console.log('No PDF files found in the new folder');
  return [];
}

// Clean and extract proper company name from folder
let companyName = folderName || 'Unknown_Company';

// Clean company name - remove common patterns that aren't company names
companyName = companyName
  .replace(/^(new folder|folder|untitled|document)$/i, 'Unknown_Company')
  .replace(/[_-]+/g, ' ')  // Replace underscores and dashes with spaces
  .replace(/\s+/g, ' ')    // Normalize spaces
  .trim();

// If it's too short or generic, mark as unknown
if (companyName.length < 2 || /^(new|folder|doc|file|temp|test)$/i.test(companyName)) {
  companyName = 'Unknown_Company';
}

console.log(`Original folder name: "${folderName}"`);
console.log(`Cleaned company name: "${companyName}"`);
console.log(`Processing ${files.length} PDF files from folder: ${folderName}`);

const results = files.map(file => {
  console.log(`Preparing file: ${file.name} (${file.id})`);
  return {
    json: {
      id: file.id,
      name: file.name,
      size: file.size,
      mimeType: file.mimeType,
      webViewLink: file.webViewLink,
      webContentLink: file.webContentLink,
      company_name: companyName,
      folder_id: folderId,
      original_folder_name: folderName
    }
  };
});

console.log(`Prepared ${results.length} PDFs for processing with company name: "${companyName}"`);
return results;

// Merge all PDFs into a single document before processing
const allInputs = $input.all();
const firstInput = allInputs[0]?.json || {};

console.log('=== PDF MERGING PROCESS ===');
console.log(`Received ${allInputs.length} PDF files to merge`);
console.log('Company:', firstInput.company_name);
console.log('Folder ID:', firstInput.folder_id);

// Collect all PDF file information
const pdfFiles = allInputs.map((input, index) => {
  const file = input.json;
  console.log(`PDF ${index + 1}: ${file.name} (${file.id}) - Size: ${file.size}`);
  return {
    id: file.id,
    name: file.name,
    size: file.size,
    downloadUrl: `https://www.googleapis.com/drive/v3/files/${file.id}?alt=media`
  };
});

// Sort files by name for consistent merging order
pdfFiles.sort((a, b) => a.name.localeCompare(b.name));

console.log('Files will be merged in this order:');
pdfFiles.forEach((file, index) => {
  console.log(`${index + 1}. ${file.name}`);
});

// Generate consistent company ID
const companyId = `comp_${firstInput.folder_id}_${firstInput.company_name.replace(/[^a-zA-Z0-9]/g, '_').toLowerCase()}_${pdfFiles.length}files`;

console.log(`Company ID: ${companyId}`);
console.log('========================');

// Return merged file information for processing
return {
  json: {
    // Consistent company ID throughout workflow
    company_id: companyId,
    company_name: firstInput.company_name,
    folder_id: firstInput.folder_id,
    original_folder_name: firstInput.original_folder_name,
    // Include all source files for download
    source_files: pdfFiles,
    file_count: pdfFiles.length,
    merge_status: 'ready_for_download'
  }
};

// Download and process ALL PDFs, merging their content
const mergeInfo = $input.first().json;
const sourceFiles = mergeInfo.source_files || [];

console.log('=== DOWNLOADING ALL PDFs FOR MERGING ===');
console.log(`Processing ${sourceFiles.length} PDF files`);
console.log('Company:', mergeInfo.company_name);
console.log('Company ID:', mergeInfo.company_id);

if (sourceFiles.length === 0) {
  console.error('❌ No source files to process!');
  return {
    json: {
      error: 'No PDF files found',
      company_id: mergeInfo.company_id,
      company_name: mergeInfo.company_name,
      folder_id: mergeInfo.folder_id
    }
  };
}

// Process ALL files and return them for individual download
const allFilesForProcessing = sourceFiles.map((file, index) => {
  console.log(`Preparing file ${index + 1}/${sourceFiles.length}: ${file.name}`);
  return {
    json: {
      // Consistent company ID
      company_id: mergeInfo.company_id,
      company_name: mergeInfo.company_name,
      folder_id: mergeInfo.folder_id,
      // Individual file info for download
      file_id: file.id,
      file_name: file.name,
      file_size: file.size,
      download_url: `https://www.googleapis.com/drive/v3/files/${file.id}?alt=media`,
      file_index: index + 1,
      total_files: sourceFiles.length,
      // Metadata
      all_file_names: sourceFiles.map(f => f.name).join(', '),
      processing_status: 'ready_for_download'
    }
  };
});

console.log(`✅ Prepared ${allFilesForProcessing.length} files for individual processing`);
console.log('All files will be downloaded and content merged');

return allFilesForProcessing;

// Extract content from current PDF file
const extractedData = $input.first().json;
const fileInfo = $node["Prepare All PDFs for Download"].json;

// Get the full extracted text content
let fullTextContent = '';
let extractionMethod = 'unknown';

if (extractedData && extractedData.data) {
  fullTextContent = extractedData.data;
  extractionMethod = 'text_extraction';
  console.log(`✅ Successfully extracted ${fullTextContent.length} characters from ${fileInfo.file_name}`);
} else {
  if (typeof extractedData === 'string') {
    fullTextContent = extractedData;
    extractionMethod = 'string_conversion';
  } else if (extractedData && typeof extractedData === 'object') {
    for (const [key, value] of Object.entries(extractedData)) {
      if (typeof value === 'string' && value.length > 10) {
        fullTextContent += value + '\n';
        extractionMethod = 'object_scanning';
      }
    }
  }

  if (!fullTextContent) {
    fullTextContent = `PDF extraction failed for ${fileInfo.file_name} - file may be image-based or corrupted`;
    extractionMethod = 'failed';
    console.log(`⚠️ Could not extract text from ${fileInfo.file_name}`);
  }
}

console.log(`File ${fileInfo.file_index}/${fileInfo.total_files}: ${fileInfo.file_name}`);
console.log(`Content length: ${fullTextContent.length} characters`);
console.log(`Extraction method: ${extractionMethod}`);

// Return individual file data with extracted content
return {
  json: {
    company_id: fileInfo.company_id,
    company_name: fileInfo.company_name,
    folder_id: fileInfo.folder_id,
    file_name: fileInfo.file_name,
    file_index: fileInfo.file_index,
    total_files: fileInfo.total_files,
    extracted_content: fullTextContent,
    extraction_method: extractionMethod,
    content_length: fullTextContent.length,
    all_file_names: fileInfo.all_file_names
  }
};

// Collect and merge ALL extracted content from all PDF files
const allExtractions = $input.all();
const firstFile = allExtractions[0]?.json || {};

console.log('=== MERGING ALL PDF CONTENT ===');
console.log(`Received ${allExtractions.length} extracted PDF files`);
console.log(`Company: ${firstFile.company_name}`);
console.log(`Company ID: ${firstFile.company_id}`);

if (allExtractions.length === 0) {
  console.error('❌ No extracted content received!');
  return {
    json: {
      error: 'No content extracted from PDFs',
      company_id: firstFile.company_id,
      company_name: firstFile.company_name
    }
  };
}

// Merge all content together
let mergedContent = '';
let totalContentLength = 0;
let successfulExtractions = 0;
let failedExtractions = 0;
const fileDetails = [];

allExtractions.forEach((extraction, index) => {
  const fileData = extraction.json;
  const content = fileData.extracted_content || '';

  console.log(`Processing file ${index + 1}: ${fileData.file_name}`);
  console.log(`  Content length: ${content.length} characters`);
  console.log(`  Extraction method: ${fileData.extraction_method}`);

  if (content && content.length > 50 && !content.includes('extraction failed')) {
    // Add file separator and content
    mergedContent += `\n\n=== CONTENT FROM: ${fileData.file_name} ===\n\n`;
    mergedContent += content;
    mergedContent += `\n\n=== END OF ${fileData.file_name} ===\n\n`;
    successfulExtractions++;
  } else {
    console.log(`  ⚠️ Skipping ${fileData.file_name} - extraction failed or insufficient content`);
    failedExtractions++;
  }

  totalContentLength += content.length;
  fileDetails.push({
    name: fileData.file_name,
    content_length: content.length,
    extraction_method: fileData.extraction_method,
    success: content.length > 50 && !content.includes('extraction failed')
  });
});

// Final data object
const finalData = {
  company_id: firstFile.company_id,
  company_name: firstFile.company_name,
  folder_id: firstFile.folder_id,
  content: mergedContent,
  processed_at: new Date().toISOString()
};

// Log results
console.log(`\n=== FINAL MERGE RESULTS ===`);
console.log(`Company ID: ${finalData.company_id}`);
console.log(`Final Company Name: ${finalData.company_name}`);
console.log(`Total files processed: ${allExtractions.length}`);
console.log(`Successful extractions: ${successfulExtractions}`);
console.log(`Failed extractions: ${failedExtractions}`);
console.log(`Total merged content length: ${mergedContent.length} characters`);
console.log(`Files processed: ${fileDetails.map(f => f.name).join(', ')}`);
console.log(`============================\n`);

return { json: finalData };

const report = $input.first().json.response || '';
const dbData = $node['Save Company Data'].json;

console.log(`Report received (Section 1): ${report.substring(0, 100)}...`);
console.log(`Company ID: ${dbData.company_id}`);
console.log(`Company name: ${dbData.company_name}`);
console.log(`Database data content length: ${dbData.content ? dbData.content.length : 'null'}`);

if (!report) {
  console.error('Report generation failed');
  return {
    json: {
      company_id: dbData.company_id,
      company_name: dbData.company_name,
      generated_content: 'Report generation failed',
      content: dbData.content
    }
  };
}

const cleanReport = report
  .replace(/\{\{[^}]*\}\}/g, '[removed-placeholder]')
  .replace(/\$json\.[\w.]+/g, '[removed-variable]')
  .replace(/\$node\[[^\]]+\]\.[\w.\[\]]+/g, '[removed-reference]')
  .replace(/\[date\]/gi, new Date().toLocaleDateString('en-US'))
  .replace(/\[company name\]/gi, dbData.company_name)
  .replace(/\[removed-placeholder\]\s*[,.]?\s*/g, '')
  .replace(/\[removed-variable\]\s*[,.]?\s*/g, '')
  .replace(/\[removed-reference\]\s*[,.]?\s*/g, '')
  .replace(/\s+/g, ' ')
  .trim();

// Validation - check for quality issues
const qualityIssues = [];
if (cleanReport.includes('{{') || cleanReport.includes('}}')) qualityIssues.push('template variables');
if (cleanReport.includes('$json') || cleanReport.includes('$node')) qualityIssues.push('code references');
if (cleanReport.includes('[company]') || cleanReport.includes('undefined')) qualityIssues.push('placeholders');
if (cleanReport.length < 200) qualityIssues.push('too short');
if (/^(.{1,50})\1+/.test(cleanReport)) qualityIssues.push('repetitive content');

if (qualityIssues.length > 0) {
  console.error(`❌ Report quality issues detected: ${qualityIssues.join(', ')}`);
  console.error('Report preview:', cleanReport.substring(0, 200));
}

console.log(`Cleaned Section 1 report: ${cleanReport.substring(0, 100)}...`);
console.log(`Passing company ID: ${dbData.company_id}`);

return {
  json: {
    company_id: dbData.company_id,
    company_name: dbData.company_name,
    generated_content: cleanReport,
    content: dbData.content,
    section_type: 'introduction_engagement_context'
  }
};

// Process feedback from checker or approver and prepare data to send back to Generate Section 1
const inputData = $input.first().json;

// Determine source of feedback
let feedbackSource = 'Unknown';
let feedbackMessage = '';

if (inputData.response && inputData.response.includes('CHECKER_RESULT: FAIL')) {
